-- The 考研 word list loaded by migration 20260930100100 (generated by `vocab-content sql`).
begin;
select plan(8);

select is((select count(*)::int from public.words), 4801, 'all 4,801 words are loaded');
select is((select name from public.books where id = '00000000-0000-4000-8000-000000000001'), '考研词汇 (ECDICT)',
  'the system book exists');
select is((select word_count from public.books where id = '00000000-0000-4000-8000-000000000001'), 4801,
  'the system book counts its words');
select is((select count(*)::int from public.book_entries
           where book_id = '00000000-0000-4000-8000-000000000001' and word_id is not null), 4801,
  'every entry links to its dictionary word');
select ok((select array_agg(position order by position) = array(select generate_series(1, 4801))
           from public.book_entries where book_id = '00000000-0000-4000-8000-000000000001'),
  'positions run from 1 to 4,801 without gaps');
select is((select headword::text from public.book_entries
           where book_id = '00000000-0000-4000-8000-000000000001' and position = 1), 'government',
  'the most frequent word comes first');
select ok((select translation_zh like E'vt. 放弃, 抛弃, 遗弃%\nn. 放任%' from public.words where headword = 'abandon'),
  'meanings keep their text and line breaks');
select is((select id from public.book_entries
           where book_id = '00000000-0000-4000-8000-000000000001' and headword = 'abandon'),
  md5('kaoyan-ecdict/abandon')::uuid, 'entry ids are stable across environments');

select * from finish();
rollback;
